sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	(function() {

		try {
			gs.info("Business rule do email rodou");

			var email = "";
			var first_name = "";

			var openedBy_sysid = current.getValue("opened_by").toString();

			var grUser = new GlideRecord("sys_user");
			if(grUser.get(openedBy_sysid)){
				email = grUser.getValue("email").toString();
				first_name = grUser.getValue("first_name").toString();
			} else {
				gs.info("deu erro na hora de achar o user");
			}

			var training_name = "";

			var training_sysid = current.getValue("training").toString();

			var grTraining = new GlideRecord("x_1593181_shark_0_training");
			if(grTraining.get(training_sysid)){
				training_name = grTraining.getValue("name").toString();
			} else {
				gs.info("deu erro na hora de achar o treinamento");
			}

			gs.info("Chegou na parte de executar o subflow");

			var inputs = {};
			inputs['user_email'] = email; // String 
			inputs['first_name'] = first_name; // String 
			inputs['training_name'] = training_name; // String 

			// Execute Synchronously: Run in foreground. Code snippet has access to outputs.
			var result = sn_fd.FlowAPI.getRunner().subflow('x_1593181_shark_0.send_deletion_email').inForeground().withInputs(inputs).run();

			gs.info("Se chegou aqui é pra ter executado o subflow");

		} catch (ex) {
			var message = ex.getMessage();
			gs.error(message);
		}

	})();

})(current, previous);
